<script setup lang="ts">
import {computed,onUnmounted,reactive,ref,shallowRef,watch} from 'vue'
import {onBeforeRouteLeave} from 'vue-router'
import { ElMessageBox } from 'element-plus'
import { feedback as ElMessage } from '../utils/feedback'
import {api,ApiError} from '../api/client'
import {can,contextGeneration,session,switchingTenant} from '../stores/session'
import {contextTransitionGuards} from '../utils/contextTransitionGuard'
import {createChangeNoticeWorkspace,emptyChangeNoticeState,type ChangeNoticeState} from '../utils/changeNoticeWorkspace'
import {changeNoticeUuid,type ChangeNoticeContext,type ChangeNoticeDetail} from '../utils/changeNoticeDrafts'
import {validInspectionText} from '../utils/inspectionTemplates'
import {worksheetAssetChoices,type WorksheetAssetChoices} from '../utils/inspectionWorksheetForm'
import {displayTime} from '../utils/display'
import ApiErrorNotice from '../components/ApiErrorNotice.vue'
import ChangeNoticeFacts from '../components/ChangeNoticeFacts.vue'
import ChangeNoticeApprovalPanel from '../components/ChangeNoticeApprovalPanel.vue'
const approvalPanel=ref<InstanceType<typeof ChangeNoticeApprovalPanel>|null>(null)
const actions={CREATE:'新建',UPDATE:'修订',ARCHIVE:'归档',RESTORE:'恢复'}
const mode=ref<'CREATE'|'UPDATE'|null>(null),baseline=shallowRef<ChangeNoticeDetail|null>(null),initial=ref(''),validation=ref(''),expandedVersion=ref<number|null>(null),lookupId=ref('')
const form=reactive({summary:'',plannedStart:'',plannedEnd:null as string|null,ticketRef:''})
const targets=ref<{id:string;name:string|null}[]>([]),targetPage=ref(0),targetRows=computed(()=>targets.value.slice(targetPage.value*10,targetPage.value*10+10))
const assetQuery=ref(''),assetApplied=ref(''),assets=shallowRef<WorksheetAssetChoices|null>(null),checkedAssets=ref<string[]>([]),assetError=shallowRef<unknown>(null),assetBusy=ref(false)
let assetEpoch=0,assetAbort:AbortController|null=null,disposed=false
const pageQuery=ref('')
const state=shallowRef<ChangeNoticeState>(emptyChangeNoticeState()),workspace=createChangeNoticeWorkspace(api,s=>{state.value=s})
const displayedRows=computed(()=>{const rows=state.value.page?.items??[],query=pageQuery.value.trim().toLocaleLowerCase();return query?rows.filter(r=>[r.id,r.applicant_id].join(' ').toLocaleLowerCase().includes(query)):rows})
const permitted=computed(()=>Boolean(session.value?.mode==='remote_test'&&session.value.user.role==='padmin'&&can('change_notice_drafts:read')&&!switchingTenant.value))
const writable=computed(()=>permitted.value&&can('change_notice_drafts:write')),canChooseAssets=computed(()=>writable.value&&can('assets:read'))
const locked=computed(()=>!writable.value||Boolean(state.value.busy)||Boolean(state.value.attempt)||assetBusy.value||Boolean(approvalPanel.value?.unresolved()))
const contextKey=computed(()=>JSON.stringify([contextGeneration.value,session.value?.tenant.id,session.value?.user.id,session.value?.permission_version,session.value?.user.role,permitted.value,writable.value,canChooseAssets.value]))
function context():ChangeNoticeContext|null{const s=session.value;return s&&permitted.value?{tenantId:s.tenant.id,actorId:s.user.id,permissionVersion:s.permission_version,role:s.user.role,canRead:true,canWrite:writable.value}:null}
function payload(){return{expected_version:baseline.value?.version??0,change_summary:form.summary,asset_ids:targets.value.map(t=>t.id),planned_start_at:form.plannedStart,planned_end_at:form.plannedEnd,ticket_id:form.ticketRef===''?null:form.ticketRef.toLowerCase()}}
const unsaved=computed(()=>mode.value!==null&&state.value.attempt?.state!=='accepted'&&(state.value.attempt?.state==='rejected'||JSON.stringify(payload())!==initial.value||assetQuery.value!==''||checkedAssets.value.length>0))
const newerVersion=computed(()=>baseline.value&&state.value.selected?.id===baseline.value.id&&state.value.selected.version>baseline.value.version)
const currentStep=computed(()=>state.value.attempt?.state==='accepted'?3:mode.value&&targets.value.length?2:1)
function clearAssets(){assetAbort?.abort();assetAbort=null;++assetEpoch;assetBusy.value=false;assets.value=null;checkedAssets.value=[];assetError.value=null;assetQuery.value='';assetApplied.value=''}
function clearEditor(){mode.value=null;baseline.value=null;initial.value='';validation.value='';targets.value=[];targetPage.value=0;expandedVersion.value=null;Object.assign(form,{summary:'',plannedStart:'',plannedEnd:null,ticketRef:''});clearAssets()}
watch(contextKey,()=>{workspace.reset(disposed?null:context());clearEditor();lookupId.value='';pageQuery.value='';if(permitted.value&&!disposed)void workspace.list()},{immediate:true,flush:'sync'})
watch(assetQuery,()=>{assetAbort?.abort();assetAbort=null;++assetEpoch;assetBusy.value=false;assets.value=null;checkedAssets.value=[];assetError.value=null},{flush:'sync'})
async function discard(){if(!unsaved.value)return true;try{await ElMessageBox.confirm('将替换尚未成功保存的报备输入和候选选择；不会自动合并到新版本。是否继续？','保留未保存输入',{confirmButtonText:'确认替换',cancelButtonText:'保留输入',type:'warning'});return true}catch{return false}}
function canPrepare(){if(disposed||!writable.value||state.value.busy||assetBusy.value)return false;if(workspace.unresolved()||approvalPanel.value?.unresolved()){ElMessage.warning('原请求结果未知，请按原请求重试，不能替换命令');return false}return true}
async function prepareCreate(){if(!canPrepare())return false;const turn=contextKey.value;if(!await discard()||disposed||turn!==contextKey.value||!writable.value||!workspace.begin())return false;clearEditor();mode.value='CREATE';initial.value=JSON.stringify(payload());return true}
async function prepareFrom(row:ChangeNoticeDetail){if(!canPrepare()||row.archived)return false;const turn=contextKey.value,target=structuredClone(row);if(!await discard()||disposed||turn!==contextKey.value||!writable.value||!workspace.begin())return false;clearEditor();baseline.value=target;mode.value='UPDATE';targets.value=target.asset_ids.map(id=>({id,name:null}));Object.assign(form,{summary:target.change_summary,plannedStart:target.planned_start_at,plannedEnd:target.planned_end_at,ticketRef:target.ticket_id??''});initial.value=JSON.stringify(payload());return true}
async function loadAssets(next=false){
 if(disposed||!mode.value||!canChooseAssets.value||locked.value)return false
 const query=assetQuery.value,cursor=next&&assets.value?.has_more&&assetApplied.value===query?assets.value.next_cursor:null;if(next&&!cursor)return false
 assets.value=null;checkedAssets.value=[];assetError.value=null
 if(query.length>100||!validInspectionText(query,100,false,false,false)){assetError.value=new ApiError(0,'INVALID_BACKUP_ASSET_QUERY','资产查询不能超过100字符或含控制字符','—');return false}
 const scope=context();if(!scope)return false;const turn=++assetEpoch,key=contextKey.value,controller=new AbortController();assetAbort=controller;assetBusy.value=true
 try{const params=new URLSearchParams({page_size:'15',q:query});if(cursor)params.set('cursor',cursor);const raw=await api.request('/assets?'+params,{signal:controller.signal});if(disposed||turn!==assetEpoch||key!==contextKey.value||controller.signal.aborted)return false;try{assets.value=worksheetAssetChoices(raw,scope)}catch{throw new ApiError(0,'INVALID_BACKUP_ASSET_CHOICES','候选设备范围或分页未通过核对，未加入目标','—')}assetApplied.value=query;return true}catch(error){if(!disposed&&turn===assetEpoch&&key===contextKey.value)assetError.value=error;return false}finally{if(!disposed&&turn===assetEpoch&&key===contextKey.value){assetBusy.value=false;assetAbort=null}}
}
function toggleAsset(id:string,checked:boolean){if(locked.value||!mode.value||!canChooseAssets.value||!assets.value?.items.some(a=>a.id===id))return false;checkedAssets.value=checked?(checkedAssets.value.includes(id)?checkedAssets.value:[...checkedAssets.value,id]):checkedAssets.value.filter(value=>value!==id);return true}
function addChecked(){if(locked.value||!mode.value||!canChooseAssets.value||!assets.value||checkedAssets.value.length===0)return false;const ids=[...new Set(checkedAssets.value)];if(ids.some(id=>!assets.value!.items.some(a=>a.id===id)))return false;const existing=new Set(targets.value.map(t=>t.id)),added=ids.filter(id=>!existing.has(id)).map(id=>assets.value!.items.find(a=>a.id===id)!);if(targets.value.length+added.length>1000){validation.value='目标超过1000项技术保护，未截断添加';return false}if(!added.length){validation.value='这些设备已经在明确目标中，不会重复加入';return false}targets.value.push(...added.map(a=>({id:a.id,name:a.name})));checkedAssets.value=[];validation.value='';targetPage.value=Math.floor((targets.value.length-1)/10);return true}
function removeTarget(index:number){if(locked.value||!Number.isInteger(index)||index<0||index>=targets.value.length)return false;targets.value.splice(index,1);targetPage.value=Math.min(targetPage.value,Math.max(0,Math.ceil(targets.value.length/10)-1));return true}
function moveTarget(index:number,offset:-1|1){if(locked.value||!Number.isInteger(index)||index<0||index>=targets.value.length||index+offset<0||index+offset>=targets.value.length)return false;const target=targets.value.splice(index,1)[0]!;targets.value.splice(index+offset,0,target);targetPage.value=Math.floor((index+offset)/10);return true}
function setEndKnown(known:boolean){if(locked.value)return;form.plannedEnd=known?form.plannedEnd??'':null}
async function browse(next=false){validation.value='';expandedVersion.value=null;return workspace.list(next)}
async function select(id:string){validation.value='';expandedVersion.value=null;return workspace.select(id)}
async function history(id:string,next=false){validation.value='';expandedVersion.value=null;return workspace.history(id,next)}
async function lookup(){const id=lookupId.value.toLowerCase();if(!changeNoticeUuid(id)){validation.value='请填写完整报备UUID；不会自动选择第一条';return false}return select(id)}
async function save(){if(disposed||locked.value||!mode.value)return false;validation.value='';const turn=contextKey.value;const success=await workspace.submit(mode.value,payload(),baseline.value);if(disposed||turn!==contextKey.value)return false;if(success)ElMessage.success('原请求收据已确认，草稿仍未审核');else if(!state.value.attempt)validation.value='请明确变更摘要、设备和UTC开始时刻；已知结束须晚于开始，可选工单仅填UUID。未发送新请求';return success}
async function retry(){const turn=contextKey.value;const success=await workspace.retry();if(success&&!disposed&&turn===contextKey.value)ElMessage.success('已恢复原请求收据，没有重复创建或修订');return success}
async function lifecycle(row:ChangeNoticeDetail,action:'ARCHIVE'|'RESTORE'){
 if(!canPrepare()||row.archived!==(action==='RESTORE'))return false;const turn=contextKey.value,target=structuredClone(row);if(!await discard()||disposed||turn!==contextKey.value)return false
 try{await ElMessageBox.confirm((action==='ARCHIVE'?'归档':'原样恢复')+'报备 '+target.id+' 并保留全部历史；不会批准、执行或抑制告警。是否继续？',action==='ARCHIVE'?'确认归档草稿':'确认原样恢复草稿',{confirmButtonText:action==='ARCHIVE'?'归档并保留历史':'原样恢复且未审核',cancelButtonText:'取消',type:'warning'})}catch{return false}
 if(disposed||turn!==contextKey.value||!writable.value||approvalPanel.value?.unresolved()||!workspace.begin())return false;clearEditor();const success=await workspace.submit(action,{expected_version:target.version},target);if(success&&!disposed&&turn===contextKey.value)ElMessage.success(action==='ARCHIVE'?'已归档并保留历史':'已原样恢复，仍未审核');return success
}
function unlockRejected(){if(state.value.attempt?.state!=='rejected'||!workspace.begin())return false;validation.value='已保留输入并解锁。版本未自动更新；冲突时先回读，再明确按当前版本重新准备';return true}
async function closeEditor(){if(workspace.unresolved()){ElMessage.warning('结果未知，不能关闭并丢失原请求');return false}const turn=contextKey.value;if(!await discard()||disposed||turn!==contextKey.value||state.value.busy)return false;if(state.value.attempt?.state==='rejected'&&!workspace.begin())return false;clearEditor();return true}
async function mayLeave(){if(workspace.unresolved()||approvalPanel.value?.unresolved()){ElMessage.warning('先确认原请求结果；普通刷新不能替代原请求重试');return false}const turn=contextKey.value;return await discard()&&(!approvalPanel.value||await approvalPanel.value.mayLeave())&&!disposed&&turn===contextKey.value}
onBeforeRouteLeave(mayLeave);const unregister=contextTransitionGuards.register(mayLeave)
function beforeUnload(event:BeforeUnloadEvent){if(workspace.unresolved()||unsaved.value||approvalPanel.value?.unresolved()||approvalPanel.value?.hasUnsaved()){event.preventDefault();event.returnValue=''}}
window.addEventListener('beforeunload',beforeUnload)
onUnmounted(()=>{disposed=true;unregister();workspace.dispose();clearEditor();window.removeEventListener('beforeunload',beforeUnload)})
defineExpose({prepareCreate,prepareFrom,loadAssets,addChecked,removeTarget,moveTarget,setEndKnown,browse,select,history,save,retry,lifecycle,unlockRejected,closeEditor,payload,form,targets,assetQuery,checkedAssets,assets,state,hasUnresolved:workspace.unresolved})
</script>
<template>
 <section class="change-notice-page">
  <div class="page-heading"><div><h1>变更报备草稿</h1><p>登记配置变更报备草稿、变更摘要与计划窗口 · 保留原申请人与修订历史</p></div><button v-if="writable" type="button" :disabled="Boolean(state.busy)||assetBusy||workspace.unresolved()" @click="prepareCreate">准备新报备草稿</button></div>
  <el-alert type="warning" :closable="false" show-icon title="待提交审批，审批流与窗口匹配规则待生效；草稿暂不触发远程执行或告警抑制" />
  <p v-if="!permitted" class="panel">当前无权读取变更报备草稿，或租户正在切换；未展示旧数据</p>
  <template v-else>
<div class="feature-summary"><article><span>本页变更报备</span><strong>{{ state.page?.items.length ?? '—' }}</strong><small>当前已读取记录，非总体数量</small></article><article><span>本页未归档</span><strong>{{ state.page ? state.page.items.filter(row => !row.archived).length : '—' }}</strong><small>仅记录状态，不表示批准或生效</small></article><article><span>当前所选版本</span><strong>{{ state.selected ? 'v'+state.selected.version : '—' }}</strong><small>按明确版本读取</small></article><article><span>未填结束时间</span><strong>{{ state.page ? state.page.items.filter(row => row.planned_end_at === null).length : '—' }}</strong><small>本页报备；未知时间不自动补齐</small></article></div>
   <details class="boundary-details"><summary>草稿准备与原请求确认说明</summary><ol class="plan-steps" aria-label="变更报备草稿步骤"><li :aria-current="currentStep===1?'step':undefined"><strong>① 明确目标</strong><span>手动勾选当前租户设备</span></li><li :aria-current="currentStep===2?'step':undefined"><strong>② 填写提案</strong><span>明确开始，结束可未知</span></li><li :aria-current="currentStep===3?'step':undefined"><strong>③ 确认原收据</strong><span>结果未知只重试原请求</span></li></ol></details>
   <ApiErrorNotice :error="state.error" />
   <section v-if="state.attempt" class="panel original-request" aria-live="polite"><h2>原请求 · {{actions[state.attempt.action]}}</h2><p v-if="state.attempt.state==='uncertain'">结果未知：可能已经提交。输入与原key/body已锁定，刷新列表不会重复提交请求</p><p v-else-if="state.attempt.state==='accepted'">已确认原请求收据；这不是当前最新状态，也不表示报备已获批准</p><p v-else>本次请求已明确拒绝。原输入保留，版本不自动合并</p><div class="actions"><button v-if="state.attempt.state==='uncertain'" type="button" :disabled="Boolean(state.busy)||!writable" @click="retry">重试提交</button><button v-if="state.attempt.state==='rejected'&&writable" type="button" :disabled="Boolean(state.busy)" @click="unlockRejected">保留输入并解锁修正</button><button v-if="state.attempt.baseline" type="button" :disabled="Boolean(state.busy)" @click="select(state.attempt.baseline.id)">查看原记录</button></div></section>

   <section v-if="state.receipt" class="panel receipt-panel"><h2>原请求确认收据 · v{{state.receipt.version}}</h2><p>{{state.receipt.id}} · {{state.receipt.archived?'已归档':'未审核草稿'}} · 不是当前最新状态</p><details><summary>查看原收据提案</summary><ChangeNoticeFacts :value="state.receipt" /></details></section>
   <div class="workspace-grid maintenance-workspace" :class="{'is-editing':Boolean(mode)}"><div class="workspace-main"><section class="panel"><nav class="feature-tabs" aria-label="变更报备工作区"><span class="active">已保存草稿</span><router-link to="/backup-plan-drafts">备份计划</router-link></nav><div class="actions"><h2>已保存草稿（含归档）</h2><button type="button" :disabled="Boolean(state.busy)" @click="browse(false)">刷新列表</button></div><div class="page-search-toolbar"><label>搜索本页记录<input v-model="pageQuery" aria-label="搜索本页变更报备记录" type="search" maxlength="200" placeholder="报备编号 / 申请人编号" /></label><button type="button" :disabled="!pageQuery" @click="pageQuery=''">清除本页搜索</button><span>仅检索本页已加载记录</span></div><details class="lookup-details"><summary>按编号精确查询</summary><div class="actions lookup"><label>明确报备UUID<input v-model="lookupId" aria-label="变更报备查询ID" maxlength="36" @keydown.enter.prevent="lookup" /></label><button type="button" :disabled="Boolean(state.busy)" @click="lookup">按ID读取当前记录</button></div></details><p v-if="validation&&!mode" role="alert" class="validation">{{validation}}</p><p v-if="!state.page" class="empty-panel">{{state.busy==='read'?'正在读取，数量未知':state.error?'读取未通过，未显示旧列表':'尚未读取，数量未知'}}</p><template v-else><div class="maintenance-table-wrap" role="region" tabindex="0" aria-label="变更报备列表，可横向滚动"><table class="maintenance-table"><colgroup><col style="width:270px" /><col style="width:120px" /><col style="width:200px" /><col style="width:140px" /><col style="width:150px" /><col style="width:130px" /></colgroup><thead><tr><th scope="col">报备编号 / 申请人</th><th scope="col">目标设备</th><th scope="col">计划窗口</th><th scope="col">状态 / 版本</th><th scope="col">记录时间</th><th scope="col">操作</th></tr></thead><tbody><tr v-for="r in displayedRows" :key="r.id"><td><strong class="record-id">{{r.id}}</strong><small>原申请人 {{r.applicant_id}}</small></td><td>{{r.asset_count}} 个设备引用</td><td>{{displayTime(r.planned_start_at)}}<small>结束 {{r.planned_end_at===null?'未指定':displayTime(r.planned_end_at)}}</small></td><td><span class="record-status">{{r.archived?'已归档':'未审核草稿'}}</span><small>v{{r.version}} · 未生效</small></td><td>{{displayTime(r.recorded_at)}}</td><td><button type="button" :disabled="Boolean(state.busy)" @click="select(r.id)">查看当前提案</button></td></tr></tbody></table></div><p v-if="state.page.items.length&&!displayedRows.length" class="empty-panel">本页没有匹配记录；清除搜索可查看已加载记录，不代表其他页没有结果</p><p v-if="!state.page.items.length">本页没有已保存草稿，不代表没有其他有效报备或设备变更</p><div class="actions"><span>本页{{state.page.items.length}}条<span v-if="pageQuery.trim()">，匹配{{displayedRows.length}}条</span> · {{state.paged?'续页':'第一页'}}，不是设备总体数量</span><button type="button" :disabled="Boolean(state.busy)||!state.page.has_more" @click="browse(true)">下一页草稿</button></div></template></section></div><aside class="workspace-side"><form v-form-feedback v-if="mode" class="panel plan-editor" @submit.prevent="save"><h2>{{mode==='CREATE'?'新报备草稿':'按明确版本编辑'}}<span v-if="baseline"> · v{{baseline.version}} · {{baseline.id}}</span></h2><p v-if="newerVersion" class="validation">已回读到更新版本；此处仍保留原版本输入，不会自动合并。请明确按当前版本重新准备</p>
    <fieldset :disabled="locked"><div class="editor-grid">
     <label class="full-width">变更摘要（最多2000 Unicode码点）<textarea v-model="form.summary" aria-label="变更报备摘要" maxlength="4000" placeholder="填写明确变更内容；原文空白与换行会保留" /></label>
     <label>计划开始（UTC，必填）<input v-model="form.plannedStart" aria-label="变更报备开始UTC" maxlength="30" placeholder="例如 2026-10-05T16:00:00Z" /><span class="hint">起止均需明确Z时区与秒，小数最多3位；不默认当前时刻，回读统一显示Asia/Shanghai</span></label>
     <div><label class="check-label"><input type="checkbox" :checked="form.plannedEnd===null" aria-label="结束时间未知" @change="setEndKnown(!($event.target as HTMLInputElement).checked)" />结束时间未指定</label><label>计划结束（UTC）<input v-model="form.plannedEnd" aria-label="变更报备结束UTC" :disabled="form.plannedEnd===null" maxlength="30" placeholder="已知时必须严格晚于开始；不会补默认窗口" /></label></div>
     <label>可选工单UUID<input v-model="form.ticketRef" aria-label="变更报备工单引用" maxlength="36" placeholder="留空表示未关联，不会自动关联最近工单" /><span class="hint">服务端核验当前租户工单存在；关联工单不代表批准</span></label>
     <div><strong>原申请人</strong><p>{{baseline?.applicant_id??session?.user.id}}</p><span class="hint">新建取当前会话，修改保留原申请人；不可输入或替换</span></div>
    </div></fieldset>
    <section class="asset-picker"><h3>① 明确选择当前租户设备</h3><p>不会自动选择第一项；已有目标不重复添加。候选名称仅供选择，不表示设备在线或SSH已授权</p><p v-if="!canChooseAssets" class="validation">缺少资产读取能力，不能新增候选；已有目标引用不会自动替换</p><fieldset :disabled="locked||!canChooseAssets"><div class="actions asset-search"><label>资产名称搜索<input v-model="assetQuery" aria-label="报备目标设备搜索" maxlength="100" @keydown.enter.prevent="loadAssets(false)" /></label><button type="button" @click="loadAssets(false)">查询目标设备</button><button type="button" :disabled="!assets?.has_more||assetQuery!==assetApplied" @click="loadAssets(true)">更多候选设备</button></div></fieldset><ApiErrorNotice :error="assetError" /><p v-if="assetBusy" aria-live="polite">正在读取候选，数量未知</p><fieldset v-if="assets" :disabled="locked||!canChooseAssets"><ul class="asset-candidates"><li v-for="a in assets.items" :key="a.id"><label class="check-label"><input type="checkbox" :checked="checkedAssets.includes(a.id)" :aria-label="'选择目标 '+a.id" @change="toggleAsset(a.id,($event.target as HTMLInputElement).checked)" /><span><strong>{{a.name}}</strong><small>{{a.id}}</small></span></label></li></ul><p v-if="!assets.items.length">当前查询没有已登记候选，不代表设备健康或已获执行授权</p><button type="button" :disabled="!checkedAssets.length" @click="addChecked">加入勾选设备</button></fieldset></section>
